local _, WFI = ...
WFI.Data.add("quest", {
  [98046] = { "La corona della terra", "Porta il Drained Vessel a Lariia, nel Temple of the Moon di Darnassus.", "<Lo sguardo dell'Arch Druid Fandral Staghelm si stringe.>\n\nSei ancora qui?\n\nPrendi la fiala e sparisci dalla mia vista, {class}. È chiaro che le mie risposte non si trovano nelle acque, proprio come prima.\n\nForse una delle sacerdotesse del Temple of the Moon, a sud, se ne sbarazzerà.\n\n<Fandral distoglie lo sguardo e smette di parlarti.>\n\nDevo cercare altrove, se si vuole che funzioni...", "Come posso aiutarti?", "Non badare all'Arch Druid, {name}. Porta il peso di molte cose in assenza di Malfurion.\n\nAspetta! Nella fiala restano ancora alcune gocce! Forse è per questo che il suo incantesimo è fallito?", 0x6a9c354f, 0xfa735665, 0x87e3b8dc, 0xa26e2aed, 0x8094bf8b, "....." },
  [98065] = { "La corona della terra", "Porta i Moonwell Remnants a Tyrande Whisperwind, nel Temple of the Moon di Darnassus.", "Devi portarla subito a Tyrande! La trasferirò per te in un contenitore più cerimoniale.\n\nNon avere paura. L'High Priestess di Elune è severa ma gentile. Protegge chiunque entri a Darnassus e porta a tutti la luce della nostra dea.\n\nSarà felice di ricevere quest'acqua sacra. La troverai proprio sopra di noi.", "Esponi la tua richiesta. Ho una città da governare e un popolo da guidare.", "Staghelm ha fatto molto in assenza del mio amato, ma non è Malfurion. E non è lui a gestire gli affari di Darnassus: quel fardello è soltanto mio.\n\n<Il volto di Tyrande si distende.>\n\nTi chiedo scusa. Come probabilmente avrai visto, abbiamo molte sfide da superare.\n\nPer ora Fandral è l'Arch Druid, e ti chiedo di rispettare il suo rango. Ma le sue faccende riguardano il druidismo, e le mie non solo Elune, ma anche il guidare il nostro popolo secondo la sua volontà.\n\nOgni goccia di quest'acqua è benedetta dalla nostra dea. Ti ringrazio per averla salvata.", 0x6a9c354f, 0x283abfd9, 0x13bb30c2, 0x073bf605, 0xf8575459, "....." },
  [98067] = { "Gli occhi delle Sentinels", "Poni delle Sentinel Owls all'ingresso delle profondità di Cenarion Hold, alla banca di Darnassus, alla locanda della Craftsman's Terrace e alla porta della città per la Sentinel Dalia Sunblade, nel Temple of the Moon di Darnassus.", "La General Feathermoon si assicura che tutte le sentinelle abbiano il tempo di pregare Elune. Una vera cacciatrice non brandisce solo la lama, ma anche i doni della dea per sconfiggere i nostri nemici.\n\nPuoi aiutarmi con i miei compiti quotidiani. Posiziona sentinelle in giro per la città: comincia dalle gallerie che portano sotto Cenarion Hold a nord, dalla banca al centro della città, dalla locanda della Craftsman's Terrace a nord-est e dalle porte della città. Le guardie possono aiutarti.\n\nC'è qualcosa che non va a Teldrassil: dobbiamo restare vigili.", nil, "Ti ringrazio per il tuo aiuto. Anche se trovo pace nei rituali quotidiani, è bello avere un momento per riflettere.", 0xf4253869, 0xe7a28828, 0x37765008, nil, 0x026be8bd, "...m." },
  [98189] = { "Restituire la statuetta", "Porta la Menethil Statuette al Captain Stoutfist, nel Menethil Keep.", "Santo cielo, è... è bellissima!\n\nLa Blind Princess doveva consegnarla a Menethil Harbor prima che accadesse la tragedia. Eravamo così vicini!\n\nCredo che dovesse essere firmata dal Captain Stoutfist, nel Menethil Keep proprio dietro di noi. Perché non hai tu l'onore di portare a termine il lavoro?", nil, nil, 0x6359787c, 0x0c8c34af, 0x67af9a56, nil, nil, "...mm" },
  [98208] = { "Il fiore dei cieli", "Recupera il Nord'el per Sylessa Duskwhisper, a Menethil Harbor.", "Sono venuta a Menethil Harbor da Auberdine, dal grande albero Teldrassil, per recuperare un fiore di grande importanza per il mio popolo.\n\nLa nave del mio popolo, la Flying Osprey, naufragò qui molte lune fa, insieme alla Kul Tiran Third Fleet. Tra il suo carico c'era il fiore noto come Nord'el, Bloom of the Heavens nella tua lingua, sbocciato sotto la luna piena sulla vetta del Mount Hyjal, la nostra antica dimora.\n\nTi prego, aiutami a recuperarlo! Il relitto si trova appena a sud della città, ma è abitato da feroci predoni murloc!", nil, nil, 0x67289a3e, 0x145af630, 0xc0d3a012, nil, nil, "...mm" },
  [98209] = { "Il fiore dei cieli", nil, nil, nil, nil, 0x67289a3e, nil, nil, nil, nil, ".mmmm" },
  [98284] = { "Campeggio 101: Enchanting", nil, "Gli incantatori rendono tutto migliore e sono sempre i benvenuti in qualsiasi accampamento nelle terre selvagge.\n\nCredo di conoscere qualcuno che può insegnarti a creare un Enchanted Lute per il tuo accampamento. È così importante trovare un po' di svago durante il riposo, e questo pizzico di magia può aiutarti a essere <pronto/pronta> ad affrontare ogni sorta di sfida quando tornerai sulla vecchia strada polverosa.", nil, nil, 0x2e9b8c15, nil, 0xb4a29ffc, nil, nil, ".m.mm" },
  [98286] = { "Campeggio 101: Enchanting", nil, "Gli incantatori rendono tutto migliore e sono sempre i benvenuti in qualsiasi accampamento nelle terre selvagge.\n\nCredo di conoscere qualcuno che può insegnarti a creare un Enchanted Lute per il tuo accampamento. È così importante trovare un po' di svago durante il riposo, e questo pizzico di magia può aiutarti a essere <pronto/pronta> ad affrontare ogni sorta di sfida quando tornerai sulla vecchia strada polverosa.", nil, nil, 0x2e9b8c15, nil, 0xb4a29ffc, nil, nil, ".m.mm" },
  [98340] = { nil, "Parla con Dendrite Starblaze nel villaggio di Nighthaven, a Moonglade.", nil, nil, nil, nil, 0x127a78ca, nil, nil, nil, "m.mmm" },
  [98386] = { "L'Alther's Mill", "Uccidi $N1 Greater Tarantula e distruggi $N2 Tarantula Eggs ad Alther's Mill per il Foreman Oslow, a Redridge.", "Orchi, gnoll, murloc. Sembra che tutto voglia impedirmi di finire questo ponte in tempo. Ora ci arriva voce che la nostra segheria è infestata dalle tarantole!\n\nSe vuoi guadagnare qualche moneta in più, andresti all'Alther's Mill, a est, a risolvere il loro problema di ragni? Quel posto per me è praticamente inutile se non posso mandarci gli operai in sicurezza a ritirare le spedizioni.\n\nAh, e se vedi il vecchio Alther, digli che mi deve qualcosa per aver ripulito il suo disastro.", nil, "La segheria è messa così male? È peggio di quanto pensassi.\n\nNon sono particolarmente schizzinoso, ma il lavoro è già abbastanza duro senza ragni che mi portano via gli operai. Grazie per l'aiuto, {name}!", 0xe7ba8f99, 0x7745e897, 0xebb117bb, nil, 0x4d3ec210, "...m." },
  [98392] = { "Oscurità nella radura", "Raccogli l'Hatescreech's Amulet, il Windmistress Gaedress' Amulet e il Witchmother Arysa's Amulet per la Sentinel Arynia Cloudsbreak, nell'Oracle Glade.", "Queste cinture... guarda bene il cuoio, {name}. Vedi la contaminazione che scorre tra le fibre?\n\nHo un sospetto sulla sua origine, ma ci serviranno altre prove per esserne sicuri.\n\nTorna nei nidi delle arpie a ovest ed elimina le loro capo. Se le loro collane portano la stessa oscurità di queste cinture, avremo la nostra risposta.", "Hai strappato gli amuleti alle capo delle arpie?", "<Arynia esamina gli amuleti.>\n\nVedi quei vortici verdi immondi dentro le gemme? È davvero opera della corruzione del fel moss.\n\nHo sentito rapporti simili da Shadowglen e da altre zone tra i rami, di questa sostanza che rivolge il nostro stesso mondo contro di noi.\n\nInformerò subito i miei superiori.", 0xaad1e9ab, 0xab3da6db, 0x662c4561, 0x5c33eda2, 0x1d4da464, "....." },
  [98393] = { nil, "Parla con Dendrite Starblaze nel villaggio di Nighthaven, a Moonglade.", nil, nil, nil, nil, 0x127a78ca, nil, nil, nil, "m.mmm" },
  [98397] = { nil, "Torna a Darnassus e parla con Mathrengyl Bearwalker, nel Cenarion Enclave.", nil, nil, nil, nil, 0x17d4d4c5, nil, nil, nil, "m.mmm" },
  [98403] = { "Odio contorto", "Uccidi $N1 Befouled Webwood e porta il Mature Fel Moss di Xethorr the Wicked a Tallonkai Swiftroot, a Dolanaar.", "Lord Melenas non ha agito da solo; obbediva agli ordini di un altro. Colui che cerchi è Xethorr the Wicked. Sembra che abbia corrotto i ragni che vivono su Teldrassil, destinando il loro veleno a qualche piano immondo.\n\nSi è stabilito nel profondo della foresta, nella zona a nord-ovest di qui nota come the Cleft. Fa' attenzione e porta degli alleati, perché con Xethorr non si scherza.\n\nElimina la sua progenie e portami tutto ciò che possa dirci di più sull'opera del satiro qui.", "<Tallonkai abbassa la voce.>\n\nXethorr cammina ancora libero?", "Avrei dovuto sapere che veniva usato per corrompere i ragni di questa terra.\n\nHo sentito sussurrare che questa sostanza è la fonte di gran parte della corruzione che ci affligge. Anche se non è l'originale, è un campione più vecchio e potrebbe fornire più informazioni di quante ne abbiamo ottenute finora.\n\nDi solito ti farei mandare questo a Darnassus per ulteriori studi. Tuttavia, per il momento è meglio tenere la cosa nascosta, o Dolanaar non recupererà mai la sua reputazione.\n\nConfido che tu faccia lo stesso.", 0x10738b8e, 0xa891e626, 0x8a01b9a3, 0x32ad7205, 0x7c0c6469, "....." },
})
